const priorityFilter = app.querySelector('#priority-filter');
const dueFromInput = app.querySelector('#due-from');
const dueThroughInput = app.querySelector('#due-through');
let appliedRange = { from: '', through: '' };
const validDate = value => {
  const match = value.match(/^(\\d{4})-(\\d{2})-(\\d{2})$/);
  if (!match) return false;
  const [, year, month, day] = match.map(Number);
  return year >= 1 && month >= 1 && month <= 12 && day >= 1 && day <= new Date(Date.UTC(year, month, 0)).getUTCDate();
};
app.querySelector('#apply-due-range').addEventListener('click', async () => {
  const from = dueFromInput.value.trim(), through = dueThroughInput.value.trim();
  if ((from && !validDate(from)) || (through && !validDate(through))) { alert.textContent = 'Due range must use valid YYYY-MM-DD dates'; alert.hidden = false; return; }
  if (from && through && from > through) { alert.textContent = 'Due from must not be after Due through'; alert.hidden = false; return; }
  appliedRange = { from, through }; alert.hidden = true; await renderTasks();
});
app.querySelector('#rename-form')

const saved = await result.json();
alert.hidden = true;
dueDate.value = saved.dueDate || '';
await renderTasks();

